package com.village.controller;
import com.village.model.VillageUser; import com.village.repository.UserRepository; import com.village.service.UserService; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/users") public class UserController{
 private final UserRepository repo; private final com.village.repository.FamilyRepository families; private final UserService service; private final PasswordEncoder encoder;
 public UserController(UserRepository r,com.village.repository.FamilyRepository f,UserService s,PasswordEncoder e){repo=r;families=f;service=s;encoder=e;}
 private void admin(Authentication a){if(a.getAuthorities().stream().noneMatch(x->x.getAuthority().equals("ROLE_ADMIN")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Admin only");}
 @GetMapping public List<Map<String,Object>> all(Authentication a){admin(a);return repo.findAll().stream().filter(u->!"ADMIN".equals(u.getRole())).map(service::safe).toList();}
 @GetMapping("/{id}") public Map<String,Object> one(@PathVariable Long id,Authentication a){admin(a);VillageUser u=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));if("ADMIN".equals(u.getRole()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Administrator information is protected");return service.safe(u);}
 @PutMapping("/profile") public Map<String,Object> profile(@RequestBody Map<String,String> in,Authentication a){VillageUser u=service.byUsername(a.getName()); if(in.containsKey("name"))u.setName(in.get("name"));if(in.containsKey("email")&&!in.get("email").equalsIgnoreCase(u.getEmail())){if(repo.existsByEmail(in.get("email")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already exists");u.setEmail(in.get("email"));}if(in.containsKey("phone"))u.setPhone(in.get("phone"));if(in.containsKey("profilePhoto"))u.setProfilePhoto(in.get("profilePhoto"));if(in.containsKey("password")&&!in.get("password").isBlank())u.setPassword(encoder.encode(in.get("password")));return service.safe(repo.save(u));}
 @PutMapping("/{id}") public Map<String,Object> update(@PathVariable Long id,@RequestBody Map<String,String> in,Authentication a){admin(a);VillageUser u=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));if("ADMIN".equals(u.getRole()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Administrator information cannot be edited here");if(in.containsKey("name"))u.setName(in.get("name"));if(in.containsKey("email"))u.setEmail(in.get("email"));if(in.containsKey("phone"))u.setPhone(in.get("phone"));if(in.containsKey("role") && !"USER".equals(in.get("role")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Users must remain USER accounts");if(in.containsKey("status"))u.setStatus(in.get("status"));return service.safe(repo.save(u));}
 @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,Authentication a){admin(a);VillageUser u=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));if("ADMIN".equals(u.getRole()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Admin accounts cannot be deleted here");families.deleteAllByUserId(u.getId());repo.delete(u);}
}
